create extension if not exists pgcrypto;
create type public.site_status as enum ('draft','demo','published','archived');
create type public.lead_status as enum ('new','contacted','won','lost');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,full_name text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.templates(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,category text[],thumbnail_url text,active boolean default true,created_at timestamptz default now());
create table public.sites(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,business_name text not null,slug text unique not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),status site_status not null default 'draft',industry text,phone text,email text,existing_website text,address text,city text,state text,zip text,service_area text,years_in_business int,business_description text,facebook_url text,instagram_url text,google_business_url text,other_social_url text,template_slug text not null default 'modern-service',logo_url text,hero_image_url text,primary_color text default '#174f3b',secondary_color text default '#e9f3ed',accent_color text default '#d4a72c',text_color text default '#17231d',background_color text default '#ffffff',font_family text default 'Inter',button_style text default 'rounded',border_radius text default '18px',logo_size text default 'medium',custom_domain text,is_published boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.site_content(id uuid primary key default gen_random_uuid(),site_id uuid unique not null references sites(id) on delete cascade,hero_eyebrow text,hero_headline text,hero_description text,hero_primary_cta text,hero_secondary_cta text,about_heading text,about_description text,services_heading text,services_description text,why_heading text,benefits jsonb default '[]',service_area_heading text,service_area_description text,contact_heading text,contact_description text,seo_title text,seo_description text,seo_keywords text[],share_title text,share_description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.services(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id) on delete cascade,name text not null,short_description text,long_description text,icon text,image_url text,sort_order int default 0,enabled boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.media(id uuid primary key default gen_random_uuid(),site_id uuid references sites(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,storage_path text unique not null,public_url text,filename text not null,mime_type text not null,caption text,alt_text text,media_type text check(media_type in ('logo','hero','gallery','service','before','after')),created_at timestamptz default now());
create table public.testimonials(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id) on delete cascade,customer_name text not null,location text,review text not null,rating int check(rating between 1 and 5),sort_order int default 0,enabled boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.faqs(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id) on delete cascade,question text not null,answer text not null,sort_order int default 0,enabled boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.business_hours(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id) on delete cascade,day_of_week int not null check(day_of_week between 0 and 6),is_closed boolean default false,open_time time,close_time time,unique(site_id,day_of_week));
create table public.site_sections(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id) on delete cascade,section_type text not null,enabled boolean default true,sort_order int default 0,unique(site_id,section_type));
create table public.ai_generations(id uuid primary key default gen_random_uuid(),site_id uuid references sites(id) on delete cascade,generation_type text not null,input jsonb,output jsonb,provider text,model text,created_at timestamptz default now());
create table public.site_leads(id uuid primary key default gen_random_uuid(),site_id uuid not null references sites(id) on delete cascade,name text not null,phone text,email text,service text,message text not null,status lead_status default 'new',created_at timestamptz default now());
create index sites_user_id_idx on sites(user_id);create index services_site_id_idx on services(site_id);create index media_user_id_idx on media(user_id);create index leads_site_id_idx on site_leads(site_id);
alter table profiles enable row level security;alter table sites enable row level security;alter table site_content enable row level security;alter table services enable row level security;alter table media enable row level security;alter table testimonials enable row level security;alter table faqs enable row level security;alter table business_hours enable row level security;alter table site_sections enable row level security;alter table ai_generations enable row level security;alter table site_leads enable row level security;
create policy "profiles own" on profiles for all using(id=auth.uid()) with check(id=auth.uid());create policy "sites own" on sites for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "sites public read" on sites for select using(status in ('demo','published'));
-- Ownership is always derived through the parent site; no client-supplied owner shortcut.
do $$ declare t text; begin foreach t in array array['site_content','services','testimonials','faqs','business_hours','site_sections','ai_generations','site_leads'] loop execute format('create policy %I on public.%I for all using (exists(select 1 from public.sites s where s.id=site_id and s.user_id=auth.uid())) with check (exists(select 1 from public.sites s where s.id=site_id and s.user_id=auth.uid()))','owner via site '||t,t);end loop;end $$;
create policy "media own" on media for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "public content" on site_content for select using(exists(select 1 from sites s where s.id=site_id and s.status in ('demo','published')));create policy "public services" on services for select using(exists(select 1 from sites s where s.id=site_id and s.status in ('demo','published')));create policy "public testimonials" on testimonials for select using(exists(select 1 from sites s where s.id=site_id and s.status in ('demo','published')));create policy "public faqs" on faqs for select using(exists(select 1 from sites s where s.id=site_id and s.status in ('demo','published')));create policy "public hours" on business_hours for select using(exists(select 1 from sites s where s.id=site_id and s.status in ('demo','published')));create policy "public lead submit" on site_leads for insert with check(exists(select 1 from sites s where s.id=site_id and s.status in ('demo','published')));
insert into templates(name,slug,description,category) values ('Modern Service','modern-service','Warm and conversion focused',array['Home services']),('Bold Contractor','bold-contractor','Strong and high contrast',array['Contractors']),('Clean Professional','clean-professional','Refined and minimal',array['Professional services']);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('site-media','site-media',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict do nothing;create policy "media upload own folder" on storage.objects for insert to authenticated with check(bucket_id='site-media' and (storage.foldername(name))[1]=auth.uid()::text);create policy "media manage own folder" on storage.objects for all to authenticated using(bucket_id='site-media' and (storage.foldername(name))[1]=auth.uid()::text);
